"use client";

import CardValues from "@/component/ui/CardValues";
import {
  Box,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  Typography,
} from "@mui/material";
import "../globals.css";
import { useContext, useState } from "react";
import { Data } from "../context/Context";
import { cards } from "../cardValues/cardValues";

function HeroSection() {
  const { totalStudents, emplpoyesCount } = useContext(Data);
  const [activeCard, setActiveCard] = useState(0);

  return (
    <Box>
      <Box
        sx={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          gap: "40px",
          flexWrap: "wrap",
        }}
      >
        {cards.map((card, index) => (
          <CardValues
            key={card.title}
            title={card.title}
            description={card.description}
            fetchData={card.fetchData}
            isPending={card.isPending}
            image={card.image}
            isActive={activeCard === index}
            onMouseEnter={() => setActiveCard(index)}
          />
        ))}
      </Box>
      <Box
        sx={{
          display: "flex",
          justifyContent: "center",
          width: "100%",
          alignItems: "center",
          gap: "40px",
          flexWrap: "wrap",
          marginTop: "20px",
        }}
      >
        <Box
          sx={{
            flexGrow: {
              xs: "1",
              sm: "1",
              md: "1",
              lg: "0",
            },
            maxWidth: "100%",
            minWidth: "320px",
            height: "261px",
            padding: "10px",
            backgroundColor: "#ffff",
            border: "2px solid #eee",
            borderRadius: "10px",
          }}
        >
          <Box
            sx={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: "10px",
            }}
          >
            <Typography>الدورة المتفوقة</Typography>
            <FormControl sx={{ width: "100px" }}>
              <InputLabel id="demo-simple-select-label">بكلوريا</InputLabel>
              <Select
                sx={{
                  backgroundColor: "#eee",
                  border: "none",
                  "&:hover": {
                    outline: "none",
                    border: "none",
                  },
                }}
                labelId="demo-simple-select-label"
                id="demo-simple-select"
                label="Age"
              >
                <MenuItem value={"علمي"}>علمي</MenuItem>
                <MenuItem value={"أدبي"}>أدبي</MenuItem>
                <MenuItem value={"تاسع"}>تاسع</MenuItem>
              </Select>
            </FormControl>
          </Box>
        </Box>
        <Box
          sx={{
            flexGrow: {
              xs: "1",
              sm: "1",
              md: "1",
              lg: "0",
            },
            minWidth: "320px",
            maxWidth: "100%",
            height: "261px",
            backgroundColor: "#eee",
          }}
        ></Box>
        <Box
          sx={{
            flexGrow: {
              xs: "1",
              sm: "1",
              md: "1",
              lg: "0",
            },
            minWidth: "320px",
            height: "261px",
            backgroundColor: "#eee",
          }}
        ></Box>
      </Box>
    </Box>
  );
}

export default HeroSection;
